from pathlib import Path
p=Path('/mnt/data/v34/app-v33.js')
s=p.read_text(encoding='utf-8')
old="""function fundGuardSummary(){const items=fundGuardItems();const required=items.reduce((a,x)=>a+x.due,0),collected=items.reduce((a,x)=>a+x.paid,0),clean=fundRows('fundGuardExpenses').filter(x=>String(x.month||state.fundMonth)===state.fundMonth).reduce((a,x)=>a+Number(x.amount||0),0),other=fundRows('fundOtherIncome').filter(x=>String(x.date||'').startsWith(state.fundMonth)&&x.destination==='guard').reduce((a,x)=>a+Number(x.amount||0),0),salary=fundGuardSalary();return {items,required,collected,uncollected:Math.max(0,required-collected),clean,other,salary,net:collected+other-salary-clean}}"""
new="""function fundGuardSummary(){const items=fundGuardItems();const gm=fundGuardMonth();const required=Number(gm?.manualRevenue??0),collected=items.reduce((a,x)=>a+x.paid,0),clean=fundRows('fundGuardExpenses').filter(x=>String(x.month||state.fundMonth)===state.fundMonth).reduce((a,x)=>a+Number(x.amount||0),0),other=fundRows('fundOtherIncome').filter(x=>String(x.date||'').startsWith(state.fundMonth)&&x.destination==='guard').reduce((a,x)=>a+Number(x.amount||0),0),salary=fundGuardSalary();return {items,required,collected,uncollected:required>0?Math.max(0,required-collected):0,clean,other,salary,net:collected+other-salary-clean}}"""
