old5="""${header('خدمة الحارس','30 ₪ افتراضيًا لكل مشمول في الشهر، ويمكنك استثناء من لا يدفع.','<div class=\"panel-actions\"><button class=\"btn primary\" data-fund-action=\"guard-settings\">إعداد الشهر</button><button class=\"btn soft\" data-fund-action=\"save-guard\">حفظ الدفعات</button></div>')}"""
new5="""${header('خدمة الحارس','المبلغ على الشخص للتوزيع والمتابعة، أما إجمالي الإيراد الفعلي فتسجله أنت يدويًا. ويمكنك استثناء من لا يدفع.','<div class=\"panel-actions\"><button class=\"btn primary\" data-fund-action=\"guard-settings\">إعداد الشهر</button><button class=\"btn soft\" data-fund-action=\"save-guard\">حفظ الدفعات</button></div>')}"""
